<?php

declare(strict_types=1);
use App\Http\Controllers\Pmbm\ApplicantController;
use App\Http\Controllers\Public\PmbmRegistrationController;
use Illuminate\Support\Facades\Route;
Route::get('/pmb', [PmbmRegistrationController::class, 'index'])->name('pmbm.public.index');
Route::get('/pmb/daftar', [PmbmRegistrationController::class, 'create'])->name('pmbm.public.create');
Route::post('/pmb/daftar', [PmbmRegistrationController::class, 'store'])->middleware('throttle:5,1')->name('pmbm.public.store');
Route::get('/pmb/berhasil/{number}', [PmbmRegistrationController::class, 'success'])->middleware('signed')->name('pmbm.public.success');
Route::get('/pmb/tanda-terima/{number}', [PmbmRegistrationController::class, 'receipt'])->middleware('signed')->name('pmbm.public.receipt');
Route::get('/pmb/status', [PmbmRegistrationController::class, 'statusForm'])->name('pmbm.status.form');
Route::get('/pmb/status/{number}', [PmbmRegistrationController::class, 'status'])->middleware('throttle:10,1')->name('pmbm.status.show');
Route::middleware(['auth','active','force-password-change'])->prefix('pmbm')->name('pmbm.')->group(function () { Route::get('/pendaftar',[ApplicantController::class,'index'])->middleware('permission:pmbm.applicant.view')->name('applicants.index'); Route::get('/pendaftar/offline',[ApplicantController::class,'create'])->middleware('permission:pmbm.applicant.create')->name('applicants.create'); Route::post('/pendaftar',[ApplicantController::class,'store'])->middleware('permission:pmbm.applicant.create')->name('applicants.store'); Route::get('/pendaftar/{applicant}/edit',[ApplicantController::class,'edit'])->middleware('permission:pmbm.applicant.update')->name('applicants.edit'); Route::put('/pendaftar/{applicant}',[ApplicantController::class,'update'])->middleware('permission:pmbm.applicant.update')->name('applicants.update'); Route::get('/pendaftar/{applicant}',[ApplicantController::class,'show'])->middleware('permission:pmbm.applicant.view')->name('applicants.show'); Route::post('/pendaftar/{applicant}/verify',[ApplicantController::class,'verify'])->middleware('permission:pmbm.document.verify')->name('applicants.verify'); Route::post('/pendaftar/{applicant}/dokumen/{document}/verify',[ApplicantController::class,'verifyDocument'])->middleware('permission:pmbm.document.verify')->name('applicants.documents.verify'); Route::post('/pendaftar/{applicant}/decision-pending',[ApplicantController::class,'markDecisionPending'])->middleware('permission:pmbm.decision.manage')->name('applicants.decision-pending'); Route::post('/pendaftar/{applicant}/fitting',[ApplicantController::class,'scheduleFitting'])->middleware('permission:pmbm.fitting.manage')->name('applicants.fitting.schedule'); Route::post('/pendaftar/{applicant}/fitting/complete',[ApplicantController::class,'completeFitting'])->middleware('permission:pmbm.fitting.manage')->name('applicants.fitting.complete'); Route::post('/pendaftar/{applicant}/interview',[ApplicantController::class,'scheduleInterview'])->middleware('permission:pmbm.interview.manage')->name('applicants.interview.schedule'); Route::post('/pendaftar/{applicant}/interview/complete',[ApplicantController::class,'completeInterview'])->middleware('permission:pmbm.interview.manage')->name('applicants.interview.complete'); Route::post('/pendaftar/{applicant}/observation/complete',[ApplicantController::class,'completeObservation'])->middleware('permission:pmbm.observation.manage')->name('applicants.observation.complete'); Route::post('/pendaftar/{applicant}/decision',[ApplicantController::class,'decide'])->middleware('permission:pmbm.decision.manage')->name('applicants.decision'); Route::post('/pendaftar/{applicant}/decision/approve',[ApplicantController::class,'approveDecision'])->middleware('permission:pmbm.decision.approve')->name('applicants.decision.approve'); Route::post('/pendaftar/{applicant}/waitlist/promote',[ApplicantController::class,'promoteWaitlist'])->middleware('permission:pmbm.decision.manage')->name('applicants.waitlist.promote'); Route::post('/pendaftar/{applicant}/enroll',[ApplicantController::class,'enroll'])->middleware('permission:pmbm.enrollment.convert')->name('applicants.enroll'); });
